// A tiny stand-in for windy.com so the real, compiled racetrack plugin can run outside Windy (borrowed from spotlog).
// It fakes: the map + markers, popups and lines, the timeline store and the point-forecast API.
// It also serves a made-up race at mock://race.json (see the bottom of this file).

(function () {
    const listeners = {};
    const evented = () => {
        const subs = {};
        let id = 0;
        return {
            on(topic, cb) { id++; (subs[topic] = subs[topic] || []).push({ id, cb }); return id; },
            off(topicOrId, cb) {
                if (typeof topicOrId === 'number') {
                    Object.values(subs).forEach(l => { const i = l.findIndex(x => x.id === topicOrId); if (i > -1) l.splice(i, 1); });
                } else if (subs[topicOrId]) {
                    subs[topicOrId] = subs[topicOrId].filter(x => x.cb !== cb);
                }
            },
            emit(topic, ...args) { (subs[topic] || []).forEach(x => x.cb(...args)); },
        };
    };

    // ---- map projection over the North Atlantic (Saint-Malo to Guadeloupe) ----
    const INIT = { north: 54, south: 10, west: -68, east: 6 };
    const BOUNDS = { ...INIT };
    const moveSubs = [];
    const dragSubs = [];
    const mapEl = () => document.getElementById('map');
    const project = (lat, lon) => {
        const el = mapEl();
        return {
            x: ((lon - BOUNDS.west) / (BOUNDS.east - BOUNDS.west)) * el.clientWidth,
            y: ((BOUNDS.north - lat) / (BOUNDS.north - BOUNDS.south)) * el.clientHeight,
        };
    };
    const unproject = (x, y) => {
        const el = mapEl();
        return {
            lat: BOUNDS.north - (y / el.clientHeight) * (BOUNDS.north - BOUNDS.south),
            lon: BOUNDS.west + (x / el.clientWidth) * (BOUNDS.east - BOUNDS.west),
        };
    };

    const live = new Set();
    class Marker {
        constructor(latlng, opts) { this.latlng = latlng; this.opts = opts || {}; this.handlers = {}; }
        place() {
            const p = project(this.latlng.lat, this.latlng.lng);
            this.el.style.left = p.x + 'px';
            this.el.style.top = p.y + 'px';
        }
        addTo() {
            const el = document.createElement('div');
            el.className = 'mock-marker ' + (this.opts.icon?.className || 'pulse');
            el.innerHTML = this.opts.icon?.html || '<span class="pulse-dot"></span>';
            el.addEventListener('click', e => { e.stopPropagation(); (this.handlers.click || []).forEach(h => h(e)); });
            // like Leaflet: mouseover / mouseout on the marker; a marker in a pane gets that pane's z-index
            el.addEventListener('mouseenter', e => (this.handlers.mouseover || []).forEach(h => h(e)));
            el.addEventListener('mouseleave', e => (this.handlers.mouseout || []).forEach(h => h(e)));
            // (Leaflet's 700+ means above the cards; here cards are at 20)
            if (this.opts.pane && panes[this.opts.pane]) { panes[this.opts.pane].els.add(el); el.style.zIndex = Number(panes[this.opts.pane].style.zIndex) >= 700 ? '21' : ''; }
            mapEl().appendChild(el);
            this.el = el;
            this.place();
            live.add(this);
            return this;
        }
        on(ev, h) { (this.handlers[ev] = this.handlers[ev] || []).push(h); return this; }
        getElement() { return this.el || null; }
        remove() { if (this.opts.pane && panes[this.opts.pane]) panes[this.opts.pane].els.delete(this.el); this.el?.remove(); live.delete(this); return this; }
    }
    // map panes (Leaflet's createPane / getPane): only their z-index matters here; cards (popups) are at 20
    const panes = {};
    // ---- popups + polylines (the bits of Leaflet Spotlog uses) ----
    let openPopup = null;
    class Popup {
        constructor(opts) { this.opts = opts || {}; this.h = {}; }
        on(ev, f) { (this.h[ev] = this.h[ev] || []).push(f); return this; }
        setLatLng(ll) { this.ll = Array.isArray(ll) ? { lat: ll[0], lng: ll[1] } : ll; return this; }
        setContent(html) { this.html = html; const c = this.el?.querySelector('.leaflet-popup-content'); if (c) c.innerHTML = html; return this; }
        getElement() { return this.el || null; }
        place() { const p = project(this.ll.lat, this.ll.lng); this.el.style.left = p.x + 'px'; this.el.style.top = p.y + 'px'; }
        openOn() {
            if (openPopup && openPopup !== this && openPopup.opts.autoClose !== false) openPopup.remove();
            this.el?.remove();
            const el = document.createElement('div');
            el.className = 'mock-popup leaflet-popup ' + (this.opts.className || '');
            el.innerHTML = '<div class="leaflet-popup-content-wrapper"><div class="leaflet-popup-content">' + this.html + '</div></div>' + (this.opts.closeButton === false ? '' : '<button class="mock-popup-x" aria-label="Close">×</button>');
            el.addEventListener('click', e => e.stopPropagation());
            el.querySelector('.mock-popup-x')?.addEventListener('click', () => this.remove());
            mapEl().appendChild(el);
            this.el = el; this.place(); live.add(this); openPopup = this;
            return this;
        }
        remove() { const was = !!this.el?.isConnected; this.el?.remove(); live.delete(this); if (openPopup === this) openPopup = null; if (was) (this.h.remove || []).forEach(f => f()); return this; }
    }
    class Polyline {
        constructor(pts, opts) { this.pts = pts.map(p => Array.isArray(p) ? { lat: p[0], lng: p[1] } : p); this.opts = opts || {}; }
        place() {
            this.path.setAttribute('points', this.pts.map(p => { const q = project(p.lat, p.lng); return q.x + ',' + q.y; }).join(' '));
        }
        addTo() {
            const ns = 'http://www.w3.org/2000/svg';
            const svg = document.createElementNS(ns, 'svg');
            svg.setAttribute('class', 'mock-line');
            const path = document.createElementNS(ns, 'polyline');
            path.setAttribute('fill', 'none');
            path.setAttribute('stroke', this.opts.color || '#d49500');
            path.setAttribute('stroke-width', this.opts.weight || 3);
            path.setAttribute('stroke-linejoin', this.opts.lineJoin || 'round');
            path.setAttribute('stroke-linecap', this.opts.lineCap || 'round');
            path.setAttribute('stroke-opacity', this.opts.opacity ?? 1);
            if (this.opts.dashArray) path.setAttribute('stroke-dasharray', this.opts.dashArray);
            svg.appendChild(path);
            mapEl().appendChild(svg);
            this.el = svg; this.path = path; this.place(); live.add(this);
            return this;
        }
        getBounds() {
            const lats = this.pts.map(p => p.lat), lngs = this.pts.map(p => p.lng);
            return { south: Math.min(...lats), north: Math.max(...lats), west: Math.min(...lngs), east: Math.max(...lngs) };
        }
        remove() { this.el?.remove(); live.delete(this); return this; }
    }
    window.addEventListener('resize', () => live.forEach(m => m.place()));
    window.L = { Marker, divIcon: o => o, popup: o => new Popup(o), polyline: (p, o) => new Polyline(p, o) };

    // ---- a very small pan/zoom so centerMap, fitBounds and GPS tracks can be seen properly ----
    // k = how many times wider than the initial view (1 = initial, 0.1 = zoomed in 10x)
    const view = { k: 1 };
    const setView = (lat, lon, k) => {
        k = Math.max(0.02, Math.min(1.6, k));
        const hw = (INIT.east - INIT.west) * k / 2, hh = (INIT.north - INIT.south) * k / 2;
        Object.assign(BOUNDS, { north: lat + hh, south: lat - hh, west: lon - hw, east: lon + hw });
        view.k = k;
        live.forEach(m => m.place());
        moveSubs.forEach(f => f(BOUNDS, view.k));
    };
    const centre = () => ({ lat: (BOUNDS.north + BOUNDS.south) / 2, lng: (BOUNDS.west + BOUNDS.east) / 2 });
    const flash = (lat, lon) => {
        const p = project(lat, lon);
        const el = document.createElement('div');
        el.className = 'mock-flash';
        el.style.left = p.x + 'px'; el.style.top = p.y + 'px';
        mapEl().appendChild(el);
        setTimeout(() => el.remove(), 1400);
    };
    const leafletMap = {
        getCenter: centre,
        getZoom: () => Math.round(4 - Math.log2(view.k)),
        createPane: name => {
            if (!panes[name]) {
                // a z-index change moves the pane's markers above (700+) or below the cards, like Leaflet's panes
                let z = '';
                const els = new Set();
                const style = {};
                Object.defineProperty(style, 'zIndex', { get: () => z, set: v => { z = String(v); els.forEach(el => { el.style.zIndex = Number(z) >= 700 ? '21' : ''; }); } });
                panes[name] = { style, els };
            }
            return panes[name];
        },
        getPane: name => panes[name],
        on: (ev, f) => { if (ev === 'zoomend' || ev === 'moveend') moveSubs.push(f); if (ev === 'dragstart') dragSubs.push(f); },
        off: (ev, f) => { [moveSubs, dragSubs].forEach(l => { const i = l.indexOf(f); if (i >= 0) l.splice(i, 1); }); },
        fitBounds: (b, o) => {
            // like Leaflet: bounds or a list of [lat, lon]; padding, or paddingTopLeft + paddingBottomRight
            if (Array.isArray(b)) b = { north: Math.max(...b.map(p => p[0])), south: Math.min(...b.map(p => p[0])), west: Math.min(...b.map(p => p[1])), east: Math.max(...b.map(p => p[1])) };
            console.log('[W.map] fitBounds', b);
            const el = mapEl();
            const tl = (o && (o.paddingTopLeft || o.padding)) || [0, 0], br = (o && (o.paddingBottomRight || o.padding)) || [0, 0];
            const w = Math.max(50, el.clientWidth - tl[0] - br[0]), h = Math.max(50, el.clientHeight - tl[1] - br[1]);
            const kx = (b.east - b.west) / (INIT.east - INIT.west) * el.clientWidth / w;
            const ky = (b.north - b.south) / (INIT.north - INIT.south) * el.clientHeight / h;
            const k = Math.max(kx, ky, 0.02, o && o.maxZoom ? Math.pow(2, 4 - o.maxZoom) : 0);
            // shift the centre so the bounds sit in the free part of the map
            const lonPx = (INIT.east - INIT.west) * k / el.clientWidth, latPx = (INIT.north - INIT.south) * k / el.clientHeight;
            setView((b.north + b.south) / 2 - (br[1] - tl[1]) / 2 * latPx, (b.west + b.east) / 2 + (br[0] - tl[0]) / 2 * lonPx, k);
        },
    };
    const centerMap = c => {
        console.log('[W.map] centerMap', c);
        setView(c.lat, c.lon, c.zoom ? Math.pow(2, 4 - c.zoom) : view.k);
        flash(c.lat, c.lon);
    };

    // mouse wheel zooms around the cursor, dragging pans (a drag never counts as a map click)
    const attach = () => {
        const el = mapEl();
        if (!el) return;
        el.addEventListener('wheel', e => {
            if (e.target.closest('.top, .bar, .sb-top, .sb-bar, .banner, .mock-popup')) return;
            e.preventDefault();
            const r = el.getBoundingClientRect();
            const at = unproject(e.clientX - r.left, e.clientY - r.top);
            const f = Math.exp(Math.max(-0.5, Math.min(0.5, e.deltaY * 0.0025)));
            const k = Math.max(0.02, Math.min(1.6, view.k * f));
            const c = centre(), ratio = k / view.k;
            setView(at.lat + (c.lat - at.lat) * ratio, at.lon + (c.lng - at.lon) * ratio, k);
        }, { passive: false });
        let drag = null, panned = false;
        el.addEventListener('pointerdown', e => {
            if (e.button !== 0 || e.target.closest('.top, .bar, .banner, .mock-popup, .label, .mock-marker')) return;
            drag = { x: e.clientX, y: e.clientY, c: centre() }; panned = false;
        });
        window.addEventListener('pointermove', e => {
            if (!drag) return;
            const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
            if (!panned && Math.hypot(dx, dy) < 5) return;
            if (!panned) dragSubs.forEach(f => f());
            panned = true;
            const lonPerPx = (BOUNDS.east - BOUNDS.west) / el.clientWidth, latPerPx = (BOUNDS.north - BOUNDS.south) / el.clientHeight;
            setView(drag.c.lat + dy * latPerPx, drag.c.lng - dx * lonPerPx, view.k);
            el.style.cursor = 'grabbing';
        });
        window.addEventListener('pointerup', () => { drag = null; el.style.cursor = ''; });
        el.addEventListener('click', e => { if (panned) { e.stopImmediatePropagation(); panned = false; } }, true);
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', attach); else attach();

    // ---- timeline ----
    const store = evented();
    const now = new Date();
    now.setMinutes(0, 0, 0);
    // a logged-in Windy Premium user (Spotlog is for Premium members). Try store.set('user', null) or store.set('subscription', null).
    const state = {
        timestamp: +now + 3 * 3600e3, product: 'ecmwf', overlay: 'wind',
        user: { id: 12345, username: 'sophia', email: 'sophia@example.com' }, subscription: 'premium', userToken: 'mock-token-12345',
    };
    store.get = k => state[k];
    store.set = (k, v) => { state[k] = v; store.emit(k, v); };

    // ---- singleclick ----
    const singleclick = evented();

    // ---- fake point forecast ----
    const MODEL_OFFSET = { ecmwf: 0, gfs: -1.6, icon: 0.9, iconEu: 0.4, arome: -0.6, mblue: 0.6 };
    const hash = (a, b) => Math.abs(Math.sin(a * 12.9898 + b * 78.233) * 43758.5453) % 1;
    const series = (model, lat, lon) => {
        const start = new Date(); start.setHours(0, 0, 0, 0);
        const out = { ts: [], hour: [], isDay: [], wind: [], windGust: [], windDir: [], temperature: [], waves: [], wavesPeriod: [], wavesPower: [], wavesDir: [], swell1: [], swell1Period: [], swell1Dir: [] };
        const base = 6 + hash(lat, lon) * 4;
        for (let i = 0; i < 24 * 8; i++) {
            const ts = +start + i * 3600e3;
            const h = new Date(ts).getHours();
            const day = Math.floor(i / 24);
            const diurnal = Math.sin(((h - 9) / 24) * Math.PI * 2) * 2.4;
            const synoptic = Math.sin(day / 1.3) * 2.2;
            // a front comes through every couple of days: calm, then a gale, so the whole colour scale shows up
            const w = Math.max(0.5, base + 1 + 9 * Math.sin(i / 8 + base) + diurnal * 0.4 + synoptic + (MODEL_OFFSET[model] || 0) + Math.sin(i / 3.1) * 0.8);
            const levante = day % 5 < 3;
            out.ts.push(ts); out.hour.push(h); out.isDay.push(h >= 8 && h <= 20 ? 1 : 0);
            out.wind.push(Math.round(w * 10) / 10);
            out.windGust.push(Math.round(w * 1.35 * 10) / 10);
            out.windDir.push(levante ? 100 + Math.sin(i / 5) * 12 : 270 + Math.sin(i / 5) * 15);
            out.temperature.push(273.15 + 19 + Math.sin(((h - 9) / 24) * Math.PI * 2) * 4);
            out.waves.push(Math.round((0.4 + w / 25) * 10) / 10);
            out.wavesPeriod.push(5 + Math.round(w / 6));
            out.wavesPower.push(Math.round((w / 8) * 10) / 10);
            out.wavesDir.push(levante ? 95 : 265);
            out.swell1.push(0.4); out.swell1Period.push(8); out.swell1Dir.push(250);
            (out.precipAmount = out.precipAmount || []).push(day === 2 && h > 12 ? 1.2 : 0);
        }
        return out;
    };
    // like Windy: daily summary with predictability, and the place's sunrise/sunset
    const summaryOf = d => Array.from({ length: 8 }, (_, k) => ({ timestamp: d.ts[0] + k * 864e5, day: new Date(d.ts[0] + k * 864e5).getDate(), predictability: Math.max(20, 92 - k * 9) }));
    const getPointForecastData = async (model, { lat, lon }, include) => {
        await new Promise(r => setTimeout(r, 250 + Math.random() * 350));
        if (model === 'arome' && lat < 41) throw new Error('AROME covers France only');
        if (!['ecmwf', 'gfs', 'icon', 'iconEu', 'arome', 'mblue', 'ecmwfWaves', 'gfsWaves'].includes(model)) throw new Error(model + ' does not cover this place');
        const d = series(model.replace('Waves', ''), lat, lon);
        const sr = new Date(); sr.setHours(7, 40, 0, 0); const ss = new Date(); ss.setHours(19, 25, 0, 0);
        return { data: { data: d, header: { model }, ...(include?.summary ? { summary: summaryOf(d) } : {}), ...(include?.celestial ? { celestial: { sunriseTs: +sr, sunsetTs: +ss } } : {}) } };
    };
    // ---- place names on the fake map (like Windy's city labels) ----
    const PLACES = [
        { name: 'Brest', lat: 48.39, lon: -4.49 }, { name: 'A Coruña', lat: 43.36, lon: -8.41 },
        { name: 'Lisbon', lat: 38.72, lon: -9.14 }, { name: 'Madeira', lat: 32.75, lon: -16.96 }, { name: 'Canary Islands', lat: 28.29, lon: -16.63 },
        { name: 'Azores', lat: 38.66, lon: -27.22 }, { name: 'Cabo Verde', lat: 15.12, lon: -23.6 }, { name: 'Antigua', lat: 17.07, lon: -61.8 },
        { name: 'Bermuda', lat: 32.3, lon: -64.78 },
    ];

    // ---- Windy's own closing ✕ (Windy draws it on every right-hand pane plugin) ----
    const addClosingX = () => {
        const pane = document.getElementById('pane');
        if (!pane || document.getElementById('w-closing-x')) return;
        const b = document.createElement('button');
        b.id = 'w-closing-x';
        b.className = 'w-closing-x';
        b.type = 'button';
        b.title = 'Windy’s own close button (stand-in)';
        b.setAttribute('aria-label', 'Close plugin');
        b.textContent = '✕';
        b.addEventListener('click', e => { e.stopPropagation(); console.log('[W] rqstClose (Windy closes the plugin)'); b.animate?.([{ transform: 'scale(.85)' }, { transform: 'scale(1)' }], 180); });
        pane.parentElement.appendChild(b);
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', addClosingX); else addClosingX();

    // like Windy: typing anywhere jumps into its search box, space plays the timeline
    document.addEventListener('keydown', e => {
        const t = e.target;
        if (e.key === ' ') { e.preventDefault(); console.log('[W] space: play timeline'); return; }
        if (e.key.length === 1 && !(t && t.id === 'mock-search')) {
            let box = document.getElementById('mock-search');
            if (!box) { box = document.createElement('input'); box.id = 'mock-search'; box.style.cssText = 'position:fixed;left:-9999px;top:0'; document.body.appendChild(box); }
            box.focus();
        }
    });

    // ---- a made-up race, served at mock://race.json and mock://track.json ----
    // ?scenario= one of (see docs/testing.md):
    //   racing (default, day 4) · quiet (no position for 5 h) · before · finished · retired · real (the repository's data/ files)
    //   empty (started 2 h ago, no position yet) · messy (duplicates, out of order, a glitch, a future point, bad rows)
    //   live (a new position every time the track is fetched) · slow (the files take 4 s) · broken (track.json isn't JSON)
    //   offline (nothing loads until window.__mockOnline = true) · cached (nothing loads; the last copy from an earlier visit shows)
    //   nophoto (the athlete's photo doesn't load: initials show)
    const scenario = new URLSearchParams(location.search).get('scenario') || 'racing';
    const KN = 1.852;
    const ROUTE = [[48.68, -2.02], [48.78, -2.6], [48.55, -5.4], [46.2, -8.2], [43.4, -10.4], [39.6, -11.8], [34.2, -17.4], [28.6, -21.6], [23.5, -31], [19.6, -43], [17.4, -53], [16.7, -60.4], [16.22, -61.53]];
    const rad = d => d * Math.PI / 180;
    const dist = (a, b) => { const h = Math.sin(rad(b[0] - a[0]) / 2) ** 2 + Math.cos(rad(a[0])) * Math.cos(rad(b[0])) * Math.sin(rad(b[1] - a[1]) / 2) ** 2; return 2 * 6371 * Math.asin(Math.sqrt(h)); };
    const legs = ROUTE.slice(1).map((p, i) => dist(ROUTE[i], p));
    const along = km => {
        let i = 0;
        while (i < legs.length - 1 && km > legs[i]) { km -= legs[i]; i++; }
        const f = Math.min(1, km / legs[i]), a = ROUTE[i], b = ROUTE[i + 1];
        return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
    };
    const iso = t => new Date(t).toISOString();
    // Milan's photo (data/milan.jpg, smaller)
    const PHOTO = 'data:image/jpeg;base64,';
    // photos of the boat: ?bg=1…11 behind the whole panel (10, far off on the dark sea, is the one in use; 0 none). Not in use, to try:
    // ?cover=1…4 fills the top card, ?boatphoto=1 puts the photo from above behind "The boat"
    const BGS = ['data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,'];
    const bgN = Number(new URLSearchParams(location.search).get('bg') ?? '10');
    const BG = bgN >= 1 && bgN <= BGS.length ? BGS[bgN - 1] : '';
    const COVERS = ['data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', 'data:image/jpeg;base64,'];
    const BOAT_TOP = 'data:image/jpeg;base64,';
    const coverN = Number(new URLSearchParams(location.search).get('cover') ?? '0');
    // the video card: ?video=wide (a normal YouTube video), short (a YouTube Short, upright), both (and an earlier one),
    // auto (found by the Action: data/videos.json); default none
    const videoQ = new URLSearchParams(location.search).get('video') || '';
    const VIDEOS = {
        wide: [{ url: 'https://www.youtube.com/watch?v=aqz-KE-bpKQ', title: 'Sample: a wide video', date: new Date(Date.now() - 5 * 3600e3).toISOString() }],
        short: [{ url: 'https://www.youtube.com/shorts/jNQXAC9IVRw', title: 'Sample: an upright video (a Short)', date: new Date(Date.now() - 2 * 3600e3).toISOString() }],
    };
    VIDEOS.both = [...VIDEOS.short, ...VIDEOS.wide];
    const COVER = coverN >= 1 && coverN <= 4 ? COVERS[coverN - 1] : '';
    const store_ = (k, v) => { try { return v === undefined ? sessionStorage.getItem(k) : sessionStorage.setItem(k, v); } catch { return null; } };
    function makeRace() {
        const now = Date.now();
        const start = scenario === 'before' ? Date.parse('2026-11-01T12:02:00Z') > now ? Date.parse('2026-11-01T12:02:00Z') : now + 4.2 * 864e5
            : scenario === 'finished' ? now - 15.5 * 864e5 : scenario === 'empty' ? now - 2 * 3600e3 : now - 4.3 * 864e5;
        const race = {
            athlete: {
                name: 'Milan Koláček', short: 'Milan', boat: 'Class40', country: 'Czechia', flag: 'CZ', photo: scenario === 'nophoto' ? 'https://photos.invalid/milan.jpg' : PHOTO, background: BG, cover: COVER, boatPhoto: new URLSearchParams(location.search).has('boatphoto') ? BOAT_TOP : '',
                about: 'Sample text: the first Czech skipper ever at the Route du Rhum. He learned to sail on the Orlík reservoir, built boats in France and races a new Mach 40.6 in the Class40 fleet.',
                url: '', links: [{ label: 'Instagram', url: 'https://www.instagram.com/milan_kolacek/' }, { label: 'Facebook', url: 'https://www.facebook.com/milankolacekracing' }],
            },
            race: {
                name: 'Route du Rhum – Destination Guadeloupe 2026', short: 'Route du Rhum 2026', url: 'https://www.routedurhum.com',
                about: 'Sample text: solo and non-stop across the Atlantic, every four years since 1978. 118 skippers in six classes this time; Class40 is the biggest fleet.',
                links: [],
            },
            start: { name: 'Saint-Malo', lat: 48.68, lon: -2.02, time: iso(start) },
            finish: { name: 'Pointe-à-Pitre', lat: 16.22, lon: -61.53 },
            status: scenario === 'finished' ? 'finished' : scenario === 'retired' ? 'retired' : 'racing',
            about: 'The first Czech skipper ever at the Route du Rhum: solo and non-stop across the Atlantic, from Saint-Malo to Guadeloupe. (Sample data for testing.)',
            follow: [{ name: 'Windy.com', links: [{ label: 'Instagram', url: 'https://www.instagram.com/windy_forecast/' }, { label: 'Facebook', url: 'https://www.facebook.com/windyforecast' }] }],
            videos: videoQ === 'auto' ? [] : VIDEOS[videoQ] || [],
            youtube: { playlist: 'PLsample12345' },
            source: 'made-up positions for this sandbox',
            track: 'track.json',
        };
        const points = [];
        // before the start: the boat in Saint-Malo's harbour, its tracker on (one position 40 min ago)
        if (scenario === 'before') points.push({ t: iso(now - 40 * 60e3), lat: 48.6458, lon: -2.0247, sog: 0, cog: null });
        if (scenario !== 'before' && scenario !== 'empty') {
            const total = legs.reduce((a, b) => a + b, 0);
            const until = scenario === 'finished' ? start + 14.2 * 864e5 : now - (scenario === 'quiet' ? 5.2 * 3600e3 : 11 * 60e3);
            let km = 0;
            for (let t = start + 15 * 60e3; t <= until && km < total; t += 15 * 60e3) {
                const h = (t - start) / 3600e3;
                const kn = 9.5 + 2.6 * Math.sin(h / 9) + 1.2 * Math.sin(h / 2.3) + (h > 60 ? 1.5 : 0);
                km += kn * KN * 0.25;
                const [lat, lon] = along(km);
                // tacks and gybes: a little to each side of the line
                const side = Math.sin(h / 5.5) * 0.18;
                points.push({ t: iso(t), lat: +(lat + side * 0.6).toFixed(4), lon: +(lon + side).toFixed(4), sog: +kn.toFixed(1), cog: null });
            }
            if (scenario === 'finished' || scenario === 'retired') race.endTime = points[points.length - 1].t;
        }
        if (scenario === 'messy') {
            // what a tracker feed can really do: send a position twice, out of order, one in the future, a glitch far away,
            // rows without a place or a time. racetrack must drop the bad ones and still show a sane boat.
            const last = points[points.length - 1];
            points.splice(points.length - 40, 0, { ...points[points.length - 30] });                          // a duplicate
            points.push({ t: iso(now + 3 * 3600e3), lat: last.lat - 1, lon: last.lon - 1, sog: 9, cog: 200 });  // from the future
            points.push({ t: iso(Date.parse(last.t) - 7 * 60e3), lat: last.lat + 6, lon: last.lon + 9, sog: 400, cog: 0 }); // a 400-knot glitch
            points.push({ t: 'not a time', lat: 40, lon: -20 }, { t: iso(now - 30 * 60e3), lat: null, lon: -20 }, { t: iso(now - 20 * 60e3), lat: 123, lon: -20 });
            points.reverse();                                                                                    // newest first
        }
        return { race, track: { updated: iso(now - 4 * 60e3), points } };
    }
    let liveFetches = 0;
    const realFetch = window.fetch.bind(window);
    const made = makeRace();
    window.fetch = async (url, opts) => {
        const u = String(url);
        if (!u.startsWith('mock://')) return realFetch(url, opts);
        await new Promise(r => setTimeout(r, scenario === 'slow' ? 4000 : 300));
        if (store_('racetrack-mock-offline') || scenario === 'cached' || (scenario === 'offline' && !window.__mockOnline)) throw new TypeError('Failed to fetch (offline)');
        // data/videos.json (what the update-track Action finds on YouTube): only with ?video=auto, otherwise not there yet
        if (/videos\.json/.test(u)) return videoQ === 'auto' ? new Response(JSON.stringify({ updated: new Date().toISOString(), videos: VIDEOS.wide }), { status: 200, headers: { 'content-type': 'application/json' } }) : new Response('Not Found', { status: 404 });
        const isTrack = /track\.json/.test(u);
        window.__mockFetches = (window.__mockFetches || 0) + 1;
        if (isTrack && scenario === 'broken') return new Response('{"points": [ {"t": "2026-11-0', { status: 200, headers: { 'content-type': 'application/json' } });
        if (isTrack && scenario === 'live') {
            // every fetch after the first brings the boat on by one position (about 3.5 km: 10 knots since the last), timed now
            liveFetches++;
            const pts = made.track.points, last = pts[pts.length - 1];
            if (liveFetches > 1) pts.push({ t: new Date().toISOString(), lat: +(last.lat - 0.02).toFixed(4), lon: +(last.lon - 0.03).toFixed(4), sog: 10.5, cog: null });
            made.track.updated = new Date().toISOString();
        }
        const body = isTrack ? made.track : made.race;
        return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
    };
    window.__racetrackDataUrl = scenario === 'real' ? new URL('../data/race.json', location.href).toString() : 'mock://race.json';

    window.W = {
        broadcast: { emit: (t, ...a) => { console.log('[W.broadcast]', t, ...a); (listeners[t] || []).slice().forEach(f => f(...a)); }, on: (t, f) => (listeners[t] = listeners[t] || []).push(f), off: (t, f) => { listeners[t] = (listeners[t] || []).filter(x => x !== f); } },
        map: { map: leafletMap, markers: { pulsatingIcon: undefined }, centerMap },
        singleclick: { singleclick },
        plugins: {},
        // the viewer's Windy units: ?units=metric for km/h · km, anything else kt · NM
        metrics: new URLSearchParams(location.search).get('units') === 'metric' ? { wind: { metric: 'km/h' }, distance: { metric: 'km' }, waves: { metric: 'm' }, temp: { metric: '°C' } } : { wind: { metric: 'kt' }, distance: { metric: 'NM' }, waves: { metric: 'm' }, temp: { metric: '°C' } },
        store,
        // Windy's words (only the ones racetrack looks for): the Wind tab of the point forecast
        trans: { t: { WIND: 'Wind' } },
        rootScope: { isMobileOrTablet: typeof matchMedia !== 'undefined' && matchMedia('(max-width: 760px)').matches },
        fetch: { getPointForecastData },
        __mock: { project, unproject, store, singleclick, PLACES, INIT, onMove: f => moveSubs.push(f), setView, view },
    };
})();
